    await move(2, 2, 3);
    assert.deepEqual(await titles(3), ['First renamed', 'Second']);
    await move(2, 3, 3);
    assert.deepEqual(await titles(3), ['First renamed', 'Second', 'Third']);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

